import type { StateRegulation } from "../../types";

/**
 * Citation-free per-state damages framing for economic loss analyses.
 * `compensationForum` is the public body that administers workers'
 * compensation (the forum, outside civil court, where a wage-loss dispute is
 * most often decided). `damagesContext` is one to three general sentences on
 * the parts of the state's damages framework an economist's report has to be
 * built around: how wrongful death and survival recoveries are measured, how
 * collateral-source payments are treated, and whether prejudgment interest
 * exists. Primary-source citations, rule numbers, rates, and cap amounts are
 * intentionally omitted; attorneys are responsible for confirming the
 * governing framework for their case.
 *
 * Two fields serve the pages that are not about an injury or a death:
 * `generalContext` is two or three sentences for the employment, commercial,
 * and family case types (how fault is allocated in a negligence-based claim,
 * how interest before judgment treats liquidated versus unliquidated sums,
 * and whether economic damages are capped), and `expertStandard` is one or
 * two sentences on what the state's courts ask of an expert before economic
 * damages testimony reaches the fact finder (a method recognized by the
 * profession, applied to the record, from a witness qualified by training),
 * written around the inquiry rather than any named standard. Neither field
 * asserts that any report is admissible; both keep the citation-free,
 * hyphen-only, figure-free rules above.
 */
export interface StateRegulationEntry extends StateRegulation {
  /** Fault allocation, interest on liquidated versus unliquidated sums, and
   * whether economic damages are capped, for the non-injury case types. */
  generalContext: string;
  /** What the state's courts ask of an economic damages expert. */
  expertStandard: string;
}

